# ============================================================
#  CROPIFY  -  complete app in one cell
#    leaf disease detection  +  live Firebase sensor dashboard
#
#  Run this, then click the dashboard link it prints.
#  The cell keeps running while the server is up. That is normal.
#  Press stop to shut it down.
# ============================================================
import os, json, base64, shutil, subprocess, socket, time, threading

REPO = "https://github.com/Danish08-10/FYP.git"
APP  = "/content/webapp"

# ---- 1. fetch the repo, only for the image assets (logo, backgrounds) ----
if not os.path.isdir(APP + "/static/assets"):
    shutil.rmtree(APP, ignore_errors=True)
    subprocess.run(["git","clone","--depth","1","--filter=blob:none","--sparse",REPO,APP], check=True)
    subprocess.run(["git","sparse-checkout","set","static"], cwd=APP, check=True)
print("1. assets fetched")

# ---- 2. write the pages and stylesheets ----
FILES = {"templates/home.html": "", "templates/prediction.html": "", "templates/result.html": "", "templates/aboutapp.html": "", "templates/login.html": "", "templates/signup.html": "", "templates/dashboard.html": "", "static/css/theme.css": "", "static/css/style.css": "", "static/css/lsstyle.css": "", "static/script.js": "", "static/signupjs.js": ""}
for rel, b64 in FILES.items():
    dst = os.path.join(APP, rel)
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    open(dst,"wb").write(base64.b64decode(b64))
print("2. wrote", len(FILES), "pages and stylesheets")

# ---- 3. treatment guidance shown beside each prediction ----
open(APP + "/treatment.json","w").write('{\n  "Bacterial Blight": "Xanthomonas citri pv. malvacearum. Remove and destroy infected debris, use certified acid-delinted seed, and avoid overhead irrigation because splashing spreads the bacteria.",\n  "Curl Virus": "Cotton leaf curl virus, carried by whitefly. Control the whitefly rather than the virus, remove infected plants early, and prefer tolerant varieties.",\n  "Healthy Leaf": "No disease or pest damage detected. Continue routine scouting and keep irrigation and nutrition steady.",\n  "Herbicide Growth Damage": "Herbicide injury and not a pathogen. Review application rate, timing and sprayer calibration, then check for drift from neighbouring fields.",\n  "Leaf Hopper Jassids": "Amrasca biguttula feeding damage. Inspect leaf undersides where nymphs sit. Treat at the local economic threshold and not on a fixed calendar.",\n  "Leaf Redding": "A physiological response and not an infection. Common causes are nitrogen or magnesium shortage, water stress and cold nights. Take a soil test first.",\n  "Leaf Variegation": "Patchy colouring, often a micronutrient shortage or a genetic trait. Check zinc, iron and magnesium, then watch whether the pattern spreads."\n}\n')
print("3. treatment guidance written")

# ---- 4. find the trained model, or ask for the zip ----
os.makedirs(APP + "/models", exist_ok=True)
def have_model():
    return os.path.exists(APP+"/models/cotton_model.keras") and os.path.exists(APP+"/models/class_names.json")
if not have_model():
    found = None
    for root,_,files in os.walk("/content"):
        if "cotton_model.keras" in files and "/webapp/" not in root+"/":
            found = root; break
    if found:
        shutil.copy(found+"/cotton_model.keras", APP+"/models/")
        if os.path.exists(found+"/class_names.json"): shutil.copy(found+"/class_names.json", APP+"/models/")
if not have_model():
    print("   no model in this session, upload training_output.zip:")
    from google.colab import files as _f
    up = _f.upload()
    shutil.unpack_archive(list(up.keys())[0], "/content/_mdl")
    for root,_,files in os.walk("/content/_mdl"):
        if "cotton_model.keras" in files:
            shutil.copy(root+"/cotton_model.keras", APP+"/models/")
            if os.path.exists(root+"/class_names.json"): shutil.copy(root+"/class_names.json", APP+"/models/")
            break
if not os.path.exists(APP+"/models/class_names.json"):
    json.dump(["Bacterial Blight","Curl Virus","Healthy Leaf","Herbicide Growth Damage","Leaf Hopper Jassids","Leaf Redding","Leaf Variegation"], open(APP+"/models/class_names.json","w"))
assert have_model(), "Model still missing. Upload training_output.zip and re-run."
print("4. model ready")

# ---- 5. write the application ----
APP_PY = '"""\nCotton leaf pest and disease detection - web application.\n\nRun locally in VS Code:\n    1. pip install -r requirements.txt\n    2. python app.py\n    3. open http://127.0.0.1:5000 in a browser\n\nThe /prediction route loads the trained model once at start-up and returns\na real prediction. The original repo returned a fixed placeholder string\nand never loaded a model.\n"""\nimport json\nimport os\nimport time\nfrom datetime import datetime\n\nimport requests\n\nimport numpy as np\nimport tensorflow as tf\nfrom flask import Flask, jsonify, render_template, request\nfrom flask_cors import CORS\nfrom tensorflow.keras.utils import img_to_array, load_img\n\napp = Flask(__name__)\nCORS(app)\n\nUPLOAD_FOLDER = os.path.join("static", "uploads")\nALLOWED_EXTENSIONS = {"png", "jpg", "jpeg"}\nIMG_SIZE = 224                       # must match the size used in training\nMODEL_PATH = os.path.join("models", "cotton_model.keras")\nLABELS_PATH = os.path.join("models", "class_names.json")\n\napp.config["UPLOAD_FOLDER"] = UPLOAD_FOLDER\nos.makedirs(UPLOAD_FOLDER, exist_ok=True)\n\nmodel = tf.keras.models.load_model(MODEL_PATH)\nclass_names = json.load(open(LABELS_PATH))\nTREATMENT = json.load(open("treatment.json"))\n\nif int(model.output_shape[-1]) != len(class_names):\n    raise ValueError("Model outputs do not match the number of labels.")\nprint("Model loaded from %s. Classes: %s" % (MODEL_PATH, class_names))\n\n\ndef allowed_file(filename):\n    if "." not in filename:\n        return False\n    return filename.rsplit(".", 1)[1].lower() in ALLOWED_EXTENSIONS\n\n\ndef prepare(path):\n    """Resize and scale exactly as in training. A mismatch ruins accuracy."""\n    img = load_img(path, target_size=(IMG_SIZE, IMG_SIZE))\n    return np.expand_dims(img_to_array(img) / 255.0, axis=0)\n\n\n@app.route("/")\ndef home():\n    return render_template("home.html")\n\n\n@app.route("/aboutapp")\ndef aboutapp():\n    return render_template("aboutapp.html")\n\n\n@app.route("/dashboard")\ndef dashboard():\n    return render_template("dashboard.html")\n\n\n\n@app.route("/login")\ndef login():\n    return render_template("login.html")\n\n\n@app.route("/signup")\ndef signup():\n    return render_template("signup.html")\n\n\n@app.route("/prediction", methods=["GET", "POST"])\ndef prediction():\n    if request.method == "GET":\n        return render_template("prediction.html")\n\n    upload = (request.files.get("file")\n              or request.files.get("image")\n              or next(iter(request.files.values()), None))\n\n    if upload is None or upload.filename == "" or not allowed_file(upload.filename):\n        return render_template("prediction.html"), 400\n\n    filename = datetime.now().strftime("%Y%m%d_%H%M%S_") + \\\n        os.path.basename(upload.filename)\n    path = os.path.join(app.config["UPLOAD_FOLDER"], filename)\n    upload.save(path)\n\n    probs = model.predict(prepare(path), verbose=0)[0]\n    index = int(np.argmax(probs))\n    label = class_names[index]\n    confidence = float(probs[index])\n\n    cure = TREATMENT.get(label, "")\n    if confidence < 0.60:\n        cure = ("Confidence %.1f percent, below the 60 percent threshold, so "\n                "confirm by inspection. " % (confidence * 100)) + cure\n\n    return render_template("result.html",\n                           filename=filename,\n                           prediction=label,\n                           Cure=cure)\n\n\n# The ESP32 writes its readings to this path every 15 seconds.\nFIREBASE_URL = ("https://cropify-9980a-default-rtdb.asia-southeast1"\n                ".firebasedatabase.app/sensors.json")\n\n# Used to spot a node that has stopped uploading. The board reports its own\n# uptime, so if that figure stops advancing between polls the board is silent.\n_last_uptime = {"value": None, "seen_at": 0.0}\n\n\n@app.route("/data")\ndef data():\n    """\n    Live sensor readings, fetched from Firebase.\n\n    Firebase holds only the most recent reading, because the board sends a PUT\n    rather than an append. If the board goes offline that last value stays in\n    the database indefinitely, which would show as live data on the dashboard.\n    The stale_for figure below guards against that.\n    """\n    try:\n        response = requests.get(FIREBASE_URL, timeout=5)\n        response.raise_for_status()\n        reading = response.json() or {}\n    except Exception as exc:                       # noqa: BLE001\n        return jsonify(ok=False, error=str(exc))\n\n    if not reading:\n        return jsonify(ok=False, error="No readings in the database yet")\n\n    now = time.time()\n    uptime = reading.get("uptime_s")\n    if uptime != _last_uptime["value"]:\n        _last_uptime["value"] = uptime\n        _last_uptime["seen_at"] = now\n    stale_for = int(now - _last_uptime["seen_at"])\n\n    return jsonify(\n        ok=True,\n        temperature=reading.get("temperature"),\n        humidity=reading.get("humidity"),\n        soil_moisture=reading.get("soil_moisture"),\n        soil_raw=reading.get("soil_raw"),\n        uptime_s=uptime,\n        stale_for=stale_for,\n    )\n\n\n@app.route("/health")\ndef health():\n    return jsonify(model_loaded=True,\n                   model_path=MODEL_PATH,\n                   img_size=IMG_SIZE,\n                   classes=class_names,\n                   parameters=int(model.count_params()))\n\n\nif __name__ == "__main__":\n    app.run(host="127.0.0.1", port=5000, debug=True)\n'
open(APP+"/app.py","w").write(APP_PY)
print("5. app.py written")

# ---- 6. install and run ----
os.system("fuser -k 5000/tcp 2>/dev/null"); time.sleep(2)
subprocess.run(["pip","install","-q","flask","flask-cors","requests"], check=False)
print("6. starting the server, the model takes about 30 seconds to load")

def announce():
    for _ in range(120):
        time.sleep(1)
        try:
            with socket.create_connection(("127.0.0.1",5000), timeout=1): break
        except OSError: continue
    from google.colab.output import eval_js
    u = eval_js("google.colab.kernel.proxyPort(5000)")
    print("\n" + "="*62)
    print("APP IS LIVE")
    print("  home        " + u)
    print("  detect      " + u + "prediction")
    print("  dashboard   " + u + "dashboard      <-- live sensor data")
    print("  raw data    " + u + "data")
    print("="*62)
    print("Screenshot the dashboard. It shows the whole system working.")
threading.Thread(target=announce, daemon=True).start()

os.chdir(APP)
get_ipython().system("python app.py")